CREATE TYPE review_status AS ENUM ('draft','in_review','approved','rejected');
ALTER TABLE listening_tests ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE reading_tests ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE writing_tasks ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE speaking_tests ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE vocabulary ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE grammar_lessons ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
ALTER TABLE youtube_resources ADD COLUMN review_status review_status NOT NULL DEFAULT 'draft', ADD COLUMN verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN explanation TEXT;
CREATE TABLE ai_evaluation_tests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), skill VARCHAR(20) NOT NULL CHECK(skill IN ('writing','speaking')), sample_text TEXT NOT NULL, expected_band NUMERIC(2,1) NOT NULL, predicted_band NUMERIC(2,1), difference NUMERIC(2,1), analysis TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), evaluated_at TIMESTAMPTZ);
CREATE TABLE privacy_settings (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, audio_recording_consent BOOLEAN NOT NULL DEFAULT FALSE, analytics_consent BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE data_deletion_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(20) NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','processing','completed','rejected')), requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), processed_at TIMESTAMPTZ, notes TEXT);
CREATE INDEX users_created_at_idx ON users(created_at DESC); CREATE INDEX writing_attempts_user_time_idx ON writing_attempts(user_id,submitted_at DESC); CREATE INDEX speaking_attempts_user_time_idx ON speaking_attempts(user_id,submitted_at DESC); CREATE INDEX evaluations_band_idx ON writing_evaluations(overall_band);
